content:
.mobileNav { display: none; }
.contactLink { color: rgb(255 255 255 / 80%); font-size: 13px; transition: color 160ms ease; }
.contactLink:visited { color: rgb(255 255 255 / 80%); }
.contactLink:hover, .contactLink:active, .contactLink:focus-visible { color: #fff; }

@media (max-width: 767px) {
  .footer { background: #fafafa; color: #171c19; border-top: 1px solid #e5e8e5; }
  .footer > div > div:first-child { display: none; }
  .trust { border-color: #e5e8e5; background: #fff; }
  .trust > div { padding: 22px 20px; gap: 18px 12px; }
  .trust > div > div { gap: 8px; }
  .trust > div > div > div:first-child { width: 28px; height: 28px; border: 0; background: transparent; }
  .trust svg { stroke: #357247; width: 19px; height: 19px; }
  .trust p:first-child { color: #252f28; font-size: 11px; font-weight: 600; line-height: 1.4; text-transform: none; letter-spacing: 0; }
  .trust p:last-child { color: #747e76; font-size: 10px; line-height: 1.4; }
  .main { padding: 28px 20px 24px; }
  .footer { font-family: var(--font-sans), Arial, sans-serif; }
  .intro { gap: 24px; padding-bottom: 20px; border-color: #e1e6e1; }
  .brand { display: grid; grid-template-columns: 1fr auto; align-items: center; gap: 12px 8px; }
  .brand > span svg { width: 120px; height: 40px; }
  .brand svg text:first-of-type { fill: #17261b; }
  .brand > p { grid-column: 1 / -1; grid-row: 2; margin: 0; color: #6b756d; font-size: 13px; line-height: 1.75; }
  .brand > div { margin: 0; gap: 4px; }
  .brand > div a { width: 44px; height: 44px; border: 1px solid #e1e7df; background: #fff; color: #34533e; }
  .newsletter { order: 1; padding: 22px 20px 18px; border-radius: 20px; background: #173d2a; color: #fff; }
  .newsletter h3 { margin: 0 0 12px; color: #fff; font-size: 23px; font-weight: 500; letter-spacing: -.035em; text-transform: none; line-height: 1.2; max-width: 24ch; text-wrap: balance; }
  .newsletter > p { color: #c1d2c6; font-size: 13px; line-height: 1.6; margin-bottom: 16px; }
  .newsletter form { gap: 8px; }
  .newsletter input { min-height: 48px; background: #fff; border: 1px solid #fff; border-radius: 10px; color: #17261b; font-size: 16px; padding: 12px; }
  .newsletter input::placeholder { color: #748177; font-size: 13px; }
  .newsletter input:focus { outline: 2px solid #a8db9b; outline-offset: 2px; }
  .newsletter button { min-height: 48px; border: 0; border-radius: 7px; background: #c4efb5; color: #173d2a; text-transform: none; font-size: 13px; font-weight: 600; letter-spacing: 0; }
  .newsletter button:hover { background: #dbf6d2; color: #173d2a; }
  .newsletter > p:last-child { color: #c1d2c6; font-size: 11px; margin: 12px 0 0; text-align: center; }
  .contact { order: 2; }
  .contact h3 { color: #203d2b; margin-bottom: 14px; font-size: 17px; font-weight: 600; text-transform: none; letter-spacing: 0; }
  .contact ul { display: grid; gap: 10px; }
  .contact li { position: relative; align-items: center; gap: 12px; margin: 0 !important; min-height: 84px; padding: 16px; border: 1px solid #e1e7df; border-radius: 16px; background: #fff; }
  .contact li > svg { box-sizing: border-box; width: 42px; height: 42px; padding: 11px; margin: 0; border-radius: 13px; background: #edf3e9; color: #355c40 !important; }
  .contact li > div { flex: 1; min-width: 0; display: flex; flex-direction: column; align-items: flex-start; gap: 2px; }
  .contact li p:first-child { color: #263e2e; font-size: 14px; font-weight: 600; text-transform: none; letter-spacing: -.01em; margin: 0; flex-shrink: 0; }
  .contact li a, .contact li p:last-child:not(:first-child) { color: #647167; font-size: 13px; text-align: left; overflow-wrap: anywhere; }
  .contact li a.contactLink,
  .contact li a.contactLink:visited { color: #405b48; font-weight: 500; }
  .contact li a.contactLink:hover,
  .contact li a.contactLink:active,
  .contact li a.contactLink:focus { color: #173d2a; }
  .contact li a.contactLink { -webkit-tap-highlight-color: rgb(53 92 64 / 12%); }
  .contact li a { display: flex; align-items: center; min-height: 24px; padding-block: 2px; }
  .contact li:has(a) { padding-right: 42px; }
  .contact li a::after { content: ""; position: absolute; inset: 0; border-radius: 16px; }
  .contact li:has(a)::after { content: ""; position: absolute; right: 18px; top: calc(50% - 4px); width: 7px; height: 7px; border-top: 1.5px solid #6d826f; border-right: 1.5px solid #6d826f; transform: rotate(45deg); pointer-events: none; }
  .contact li:has(a:focus-visible) { outline: 2px solid #6e9c6d; outline-offset: 3px; }
  .contact li a:focus-visible { outline: none; }
  @media (hover: hover) {
    .contact li:has(a):hover { background: #f3f7f0; border-color: #b8cbb6; }
  }
  .contact li:has(a):active { background: #e5efdf; border-color: #93af8d; }
  .mobileNav { display: grid; grid-template-columns: minmax(0,1fr); gap: 0; margin-top: 20px; padding: 4px 18px; border: 1px solid #e0e7dd; border-radius: 20px; background: #fff; }
  .mobileNav details { background: transparent; }
  .mobileNav details + details { border-top: 1px solid #e9eee5; }
  .mobileNav summary { display: flex; align-items: center; justify-content: space-between; gap: 12px; list-style: none; cursor: pointer; min-height: 62px; padding: 14px 0; border-radius: 8px; color: #293d2e; font-size: 15px; font-weight: 500; letter-spacing: -.015em; }
  .mobileNav summary::-webkit-details-marker { display: none; }
  .mobileNav summary span { display: grid; place-items: center; flex-shrink: 0; width: 28px; height: 28px; border-radius: 50%; background: transparent; color: #42634b; }
  .mobileNav details[open] summary { color: #173d2a; font-weight: 650; }
  .mobileNav details[open] summary span { background: #eaf2e4; }
  .mobileNav details[open] summary svg { transform: rotate(180deg); }
  .mobileNav ul { margin: 0 0 14px; padding: 4px 12px; border-radius: 12px; background: #f5f8f2; }
  .mobileNav li + li { border-top: 1px solid #eef1eb; }
  .mobileNav a { display: flex; align-items: center; justify-content: space-between; gap: 16px; min-height: 48px; padding: 10px 4px; border-radius: 6px; color: #405b48; font-size: 13px; line-height: 1.5; overflow-wrap: anywhere; }
  .mobileNav a::after { content: ""; flex-shrink: 0; width: 6px; height: 6px; margin-right: 4px; border-top: 1.5px solid #7a8c7c; border-right: 1.5px solid #7a8c7c; transform: rotate(45deg); }
  .mobileNav a:active { background: #e5efdf; color: #173d2a; }
  @media (hover: hover) {
    .mobileNav a:hover { background: #f3f7f0; color: #173d2a; }
    .mobileNav summary:hover { color: #173d2a; }
    .mobileNav summary:hover span { background: #eaf2e4; }
  }
  .footer a:focus-visible, .footer summary:focus-visible, .footer button:focus-visible { outline: 2px solid #6e9c6d; outline-offset: 3px; }
  .bottom { color: #657268; font-size: 12px; line-height: 1.8; text-align: center; gap: 18px; padding: 20px 0 calc(100px + env(safe-area-inset-bottom, 0px)); }
  .bottom .copyright { max-width: 100%; line-height: 1.7; }
  .copyrightBrand { color: #334c3b; font-weight: 600; }
  .copyrightRights { display: block; font-size: 11px; color: #69766d; }
  .madeInMorocco { display: block; margin-top: 8px; color: #57695d; font-size: 12px; }
  .madeInMorocco span { color: #517b4c; padding-inline: 2px; }
  .bottom > div:last-child { order: -1; width: 100%; display: flex; flex-wrap: wrap; justify-content: center; gap: 0 20px; padding-bottom: 12px; border-bottom: 1px solid #e1e7df; }
  .newsletter form p { line-height: 1.5; }
  .newsletter form p[role="alert"] { color: #ffc8c8; }
  .bottom a { display: inline-flex; justify-content: center; min-height: 44px; align-items: center; color: #405b48; }
  .bottom a:hover, .bottom a:active { color: #173d2a; text-decoration: underline; text-underline-offset: 4px; }
}

@media (max-width: 359px) {
  .main { padding-inline: 16px; }
  .brand { grid-template-columns: 1fr; }
  .brand > div { grid-row: 3; }
  .newsletter { padding-inline: 16px; }
}

@media (prefers-reduced-motion: reduce) {
  .contactLink { transition: none; }
}
